V=/var/lib/docker/volumes/koha-test_koha_setup/_data
echo '' | base64 -d > /tmp/kt1.php
docker cp $V/api.key filenest-app:/tmp/k.key; docker cp $V/api.pass filenest-app:/tmp/k.pass
docker exec filenest-app chown www-data /tmp/k.key /tmp/k.pass
docker cp /tmp/kt1.php filenest-app:/tmp/kt1.php; rm -f /tmp/kt1.php
docker exec -u www-data -w /var/www/html filenest-app php -r "require 'vendor/autoload.php'; \$app = require 'bootstrap/app.php'; \$app->make(Illuminate\Contracts\Console\Kernel::class)->bootstrap(); require '/tmp/kt1.php';" 2>&1 | tail -12
docker exec filenest-app rm -f /tmp/kt1.php /tmp/k.key /tmp/k.pass
